import fs from'node:fs';import path from'node:path';import crypto from'node:crypto';import{spawnSync}from'node:child_process';
const root=import.meta.dirname,out=fs.mkdtempSync(path.join(root,'build-')),sources=path.join(out,'sources'),install=path.join(out,'install');fs.mkdirSync(sources);fs.mkdirSync(install);
const steps=[],inputs=[],env={...process.env,MACOSX_DEPLOYMENT_TARGET:'13.0',CC:'/usr/bin/clang',CXX:'/usr/bin/clang++'};let failure=null;
const pin=p=>{const b=fs.readFileSync(p);return{path:p,bytes:b.length,sha256:crypto.createHash('sha256').update(b).digest('hex')};};
function run(name,cmd,args,cwd=out){const p=spawnSync(cmd,args,{cwd,env,encoding:'utf8',maxBuffer:128*1024*1024});fs.writeFileSync(path.join(out,name+'.stdout'),p.stdout??'');fs.writeFileSync(path.join(out,name+'.stderr'),p.stderr??'');steps.push({name,cmd,args,cwd,status:p.status,signal:p.signal});console.log(name+':'+p.status);if(p.status!==0)throw Error(name+':'+p.status);return p.stdout;}
const archives=[{name:'openssl',version:'3.6.4',url:'https://github.com/openssl/openssl/releases/download/openssl-3.6.4/openssl-3.6.4.tar.gz',sha256:'9bffaa1ad1e07b354c21bd3324ec02fa15579f45a7d0494b3e74bc449b7333ef',directory:'openssl-3.6.4'},{name:'libuv',version:'1.52.1',url:'https://dist.libuv.org/dist/v1.52.1/libuv-v1.52.1.tar.gz',sha256:'66d511b9e6e334c0e62279eb234fbfb2b3110b1479c09b95b44c7afca8cff9e7',directory:'libuv-v1.52.1'}];
try{
 for(const a of archives){const file=path.join(sources,a.directory+'.tar.gz');run(a.name+'-fetch','/usr/bin/curl',['--fail','--location','--proto','=https','--tlsv1.2','--connect-timeout','20','--max-time','180','--output',file,a.url]);const actual=pin(file);if(actual.sha256!==a.sha256)throw Error('UPSTREAM_SOURCE_SHA_DIFFERS:'+a.name);inputs.push({...actual,url:a.url,version:a.version});const listing=run(a.name+'-archive-list','/usr/bin/tar',['-tf',file]);for(const item of listing.split('\n').filter(Boolean))if(item.startsWith('/')||item.split('/').includes('..')||!item.startsWith(a.directory+'/'))throw Error('ARCHIVE_PATH_OUTSIDE_OWN_SOURCE');run(a.name+'-extract','/usr/bin/tar',['--no-same-owner','--no-same-permissions','-xzf',file,'-C',sources]);}
 const openssl=path.join(sources,archives[0].directory),opensslInstall=path.join(install,'openssl');
 run('openssl-configure','/usr/bin/perl',['./Configure','darwin64-arm64-cc','shared','no-tests','--prefix='+opensslInstall,'--openssldir='+path.join(opensslInstall,'ssl'),'-mmacosx-version-min=13.0'],openssl);
 run('openssl-build-libs','/usr/bin/make',['-j2','build_libs'],openssl);
 run('openssl-install-dev','/usr/bin/make',['install_dev'],openssl);
 const uv=path.join(sources,archives[1].directory),uvBuild=path.join(out,'libuv-build'),uvInstall=path.join(install,'libuv');
 run('libuv-configure','/opt/homebrew/bin/cmake',['-S',uv,'-B',uvBuild,'-DCMAKE_BUILD_TYPE=Release','-DCMAKE_OSX_DEPLOYMENT_TARGET=13.0','-DCMAKE_OSX_ARCHITECTURES=arm64','-DCMAKE_INSTALL_PREFIX='+uvInstall,'-DLIBUV_BUILD_TESTS=OFF','-DLIBUV_BUILD_BENCH=OFF','-DBUILD_TESTING=OFF','-DLIBUV_BUILD_SHARED=ON']);
 run('libuv-build','/opt/homebrew/bin/cmake',['--build',uvBuild,'--parallel','2']);run('libuv-install','/opt/homebrew/bin/cmake',['--install',uvBuild]);
 const libraries=[path.join(opensslInstall,'lib/libssl.3.dylib'),path.join(opensslInstall,'lib/libcrypto.3.dylib'),fs.realpathSync(path.join(uvInstall,'lib/libuv.1.dylib'))];
 for(const[i,p]of libraries.entries()){run('library-'+i+'-build-version','/usr/bin/xcrun',['vtool','-show-build',p]);run('library-'+i+'-dependencies','/usr/bin/otool',['-L',p]);}
}catch(e){failure=String(e);}
const libraries=[];for(const p of[path.join(install,'openssl/lib/libssl.3.dylib'),path.join(install,'openssl/lib/libcrypto.3.dylib'),path.join(install,'libuv/lib/libuv.1.dylib')])if(fs.existsSync(p))libraries.push(pin(fs.realpathSync(p)));
fs.writeFileSync(path.join(out,'RESULT.json'),JSON.stringify({version:1,sourceArchives:inputs,steps,failure,passed:failure===null,install,libraries,target:'arm64-apple-macosx13.0',deploymentTargetEnvironment:'13.0',sourceAlgorithmsUnmodified:true,compilerParallelism:2,privateKeysRead:false,SourceSigned:false,RootAdmission:false,SourceAdmission:false,installedProduct:false},null,2)+'\n');console.log(out);if(failure)process.exitCode=1;
